const fs = require("node:fs");
const report = fs.openSync("report.txt", "w+");
fs.writeSync(report, "report: " + "ready\n", null, "utf8");
fs.closeSync(report);

const fs = require("node:fs");
const stream = fs.openSync("events.log", "a");
const mirror = stream;
fs.writeSync(mirror, "β\n", null, "utf8");
fs.writeSync(stream, "end\n", null, "utf8");
fs.closeSync(stream);

const fs = require("node:fs");
const labels = fs.openSync("labels.txt", "r+");
fs.writeSync(labels, "UP", 3, "utf8");
fs.closeSync(labels);

const fs = require("node:fs");
const note = fs.openSync("./notes/./done.txt", "r+");
fs.writeSync(note, "done", 0, "utf8");
fs.closeSync(note);

const fs = require("node:fs");
const route = fs.readFileSync("route.txt", "utf8");
const display = fs.openSync("display.txt", "w");
fs.writeSync(display, route.replace("\r\n", "\n"), 0, "utf8");
fs.closeSync(display);

const fs = require("node:fs");
const marking = fs.readFileSync("marking.txt", "utf8");
const output = fs.openSync("marking.txt", "r+");
fs.writeSync(output, marking.slice(0, 2) + "!", 0, "utf8");
fs.closeSync(output);

const fs = require("node:fs");
const health = fs.openSync("health.txt", "r+");
false && absentCleanup(health);
fs.writeSync(health, "OK\n", 0, "utf8");
fs.closeSync(health);

const fs = require("node:fs");
const closed = fs.openSync("closed.txt", "r+");
fs.closeSync(closed);
fs.writeSync(closed, "oops", 0, "utf8");

const fs = require("node:fs");
let destination = fs.openSync("rebound.txt", "r+");
destination = 1;
fs.writeSync(destination, "not-file\n", null, "utf8");

const fs = require("node:fs");
const dependency = fs.readFileSync("dependency.txt", "utf8");
const count = Number(process.env.SLICE_END);
const result = fs.openSync("dependent.txt", "r+");
fs.writeSync(result, dependency.slice(0, count), 0, "utf8");
fs.closeSync(result);

const fs = require("node:fs");
const selected = fs.openSync(process.env.OUTPUT_FILE, "r+");
fs.writeSync(selected, "path\n", 0, "utf8");
fs.closeSync(selected);

const fs = require("node:fs");
const guarded = fs.openSync("guarded.txt", "r+");
const missing = null;
missing.value;
fs.writeSync(guarded, "bad", 0, "utf8");

const fs = require("node:fs");
const skipped = fs.openSync("skipped.txt", "r+");
false && fs.writeSync(skipped, "bad", 0, "utf8");
fs.closeSync(skipped);

const fs = require("node:fs");
const split = fs.openSync("split.txt", "r+");
fs.writeSync(split, "Q", 1, "utf8");
fs.closeSync(split);
